export interface ConnectorConfig {
  /** Slack bot token with chat:write scope. */
  slackBotToken: string
  /** Slack channel ID to post the message to. */
  channel: string
  /** Optional fetch implementation for testing or custom HTTP clients. */
  fetch?: typeof fetch
}

export interface CalendlyInviteePayload {
  invitee: {
    name: string
    email: string
    answers?: Array<{
      question: string
      answer: string
    }>
  }
}

export interface HandleResult {
  /** Slack message timestamp (ts) from the response. */
  ts: string
  /** Slack channel ID where the message was posted. */
  channel: string
  /** Indicates the message was posted successfully. */
  ok: true
}

function formatMessage(payload: CalendlyInviteePayload): string {
  const { name, email, answers = [] } = payload.invitee
  const lines = [name, email]
  for (const { question, answer } of answers) {
    lines.push(`- ${question}: ${answer}`)
  }
  return lines.join('\n')
}

export async function handle(
  payload: CalendlyInviteePayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  if (!payload.invitee?.name) {
    throw new Error('Missing required field: invitee.name')
  }
  if (!payload.invitee?.email) {
    throw new Error('Missing required field: invitee.email')
  }
  if (!config.slackBotToken) {
    throw new Error('Missing required config: slackBotToken')
  }
  if (!config.channel) {
    throw new Error('Missing required config: channel')
  }

  const fetchImpl = config.fetch ?? fetch
  const text = formatMessage(payload)

  const response = await fetchImpl('https://slack.com/api/chat.postMessage', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ channel: config.channel, text }),
  })

  if (!response.ok) {
    throw new Error(`Slack chat.postMessage failed with status ${response.status}`)
  }

  const data = (await response.json()) as { ok: boolean; channel: string; ts: string }
  if (!data.ok) {
    throw new Error('Slack API returned ok: false')
  }

  return { ok: true, channel: data.channel, ts: data.ts }
}

