      expect(body.text).toContain('jane.doe@example.com')
      expect(body.text).toContain('- What is your company?: Acme Corp')
      expect(body.text).toContain('- How did you hear about us?: Google search')
      return jsonResponse({ ok: true, channel: 'C01JASD6802', ts: '1234567890.123456' })
    })

