      invitee: {
        name: 'Jane Doe',
        email: 'jane.doe@example.com',
        answers: [
          { question: 'What is your company?', answer: 'Acme Corp' },
          { question: 'How did you hear about us?', answer: 'Google search' },
        ],
      },
    }

    const result = await handle(payload, {
      slackBotToken: 'xoxb-test-token',
      channel: 'C01JASD6802',
      fetch,
    })

    expect(result).toEqual({ ok: true, channel: 'C01JASD6802', ts: '1234567890.123456' })
    expect(calls).toHaveLength(1)
  })

  it('uses Bearer token authentication', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.headers.get('authorization')).toBe('Bearer xoxb-secret-token')
      return jsonResponse({ ok: true, channel: 'C123', ts: '1.2' })
    })

    await handle(
      { invitee: { name: 'Test', email: 'test@example.com' } },
      { slackBotToken: 'xoxb-secret-token', channel: 'C123', fetch },
    )

    expect(calls[0].headers.get('authorization')).toBe('Bearer xoxb-secret-token')
  })

  it('maps invitee name, email, and answers to Slack text field', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      const body = req.json as { text: string }
      expect(body.text).toBe('John Smith\njohn@example.com\n- Favorite color?: Blue')
      return jsonResponse({ ok: true, channel: 'C1', ts: '1' })
    })

    await handle(
      {
        invitee: {
          name: 'John Smith',
          email: 'john@example.com',
          answers: [{ question: 'Favorite color?', answer: 'Blue' }],
        },
      },
      { slackBotToken: 'token', channel: 'C1', fetch },
    )

    expect(calls).toHaveLength(1)
  })

  it('handles empty answers array', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      const body = req.json as { text: string }
      expect(body.text).toBe('Solo User\nsolo@example.com')
      return jsonResponse({ ok: true, channel: 'C1', ts: '1' })
    })

    await handle(
      { invitee: { name: 'Solo User', email: 'solo@example.com', answers: [] } },
      { slackBotToken: 'token', channel: 'C1', fetch },
    )

    expect(calls).toHaveLength(1)
  })

  it('throws when invitee.name is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))

    await expect(
      handle({ invitee: { email: 'test@example.com' } } as unknown as CalendlyInviteePayload, {
        slackBotToken: 'token',
        channel: 'C1',
        fetch,
      }),
    ).rejects.toThrow('Missing required field: invitee.name')
  })

