    const { fetch } = fakeFetch(() => jsonResponse({}, 200))

    await expect(
      handle({ invitee: { name: 'Test' } } as unknown as CalendlyInviteePayload, {
        slackBotToken: 'token',
        channel: 'C1',
        fetch,
      }),
