      handle({ invitee: { name: 'Test', email: 'test@example.com' } }, { channel: 'C1', fetch } as unknown as ConnectorConfig),
    ).rejects.toThrow('Missing required config: slackBotToken')
  })

  it('throws when channel config is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))

